    opencode: ["opencode"],
    // kiro-ide is a desktop app driven over CDP: no CLI to run in a pane.
    "kiro-ide": ["bash", "-i"],
    kiro: ["kiro-cli", "chat", "--trust-all-tools"],
    codex: ["codex", "--full-auto"],
