  // Outcome columns (#29/#30): shown only when some group carries a verify
  // verdict (row.passRate); a group without one renders n/a, never 0%.
  var OUTCOME_COLS = ["passRate", "passCi", "passHatK", "anyPassAtK"];
  var LABELS = {
    experiment: "experiment", variant: "variant", workflow: "workflow", agent: "agent",
    runs: "runs", avgTotalTokens: "avg tokens", avgCostUsd: "avg cost",
    avgDurationMs: "avg duration", successRate: "success",
    passRate: "pass", passCi: "pass@1 · 95% CI", passHatK: "pass^k", anyPassAtK: "any-pass@k",
  };

  // per-table state: rows in group order + current sort (null | key+dir)
  var stores = {};

  function isMetric(key) { return METRIC_COLS.indexOf(key) !== -1 || OUTCOME_COLS.indexOf(key) !== -1; }
  function hasOutcomes(rows) {
    for (var i = 0; i < rows.length; i++) if (rows[i].passRate !== undefined && rows[i].passRate !== null) return true;
    return false;
  }
  function metricValue(row, key) {
    var rep = row.repeats || null;
    if (key === "passCi") return rep ? rep.wilsonLo : undefined;
    if (key === "passHatK" || key === "anyPassAtK") return rep ? rep[key] : undefined;
    return row[key];
  }
