    if (!sock || sock.readyState !== 1 || dead) return;
    if (term.cols === lastCols && term.rows === lastRows) return;
    lastCols = term.cols; lastRows = term.rows;
    sock.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
